#!/bin/bash
# Apply the denniz changes to the MT6891-Mainline tree on a local branch "denniz" and commit them.
#  - embedded board DTB = mt6893-oneplus-denniz.dts (generated by mk-denniz-dts.py)
#  - head.S / log_store driver: second framebuffer candidate 0x77a20000 (chopin) -> 0x78810000 (denniz
#    mblock framebuffer region 0x78810000..0x7a600000); on denniz 0x77a20000 is ordinary RAM
#  - denniz_defconfig = chopin_defconfig minus DRM/SCP/sensorhub/connectivity/FB stripes, own cmdline
set -euo pipefail
N=/srv/nord2-pmos; K=$N/src/linux-mt6893; cd $K
git rev-parse --verify -q denniz >/dev/null || git checkout -q -b denniz
git config user.name >/dev/null || git config user.name "nord2-build"
git config user.email >/dev/null || git config user.email "nord2-build@localhost"
python3 $N/repo/scripts/mk-denniz-dts.py arch/arm64/boot/dts/mediatek/mt6893-xiaomi-chopin.dts \
  $N/tests/twrp-hwinfo-20261114/live.dts arch/arm64/boot/dts/mediatek/mt6893-oneplus-denniz.dts
grep -q oneplus-denniz arch/arm64/boot/dts/mediatek/Makefile || \
  sed -i 's/^dtb-$(CONFIG_ARCH_MEDIATEK) += mt6893-xiaomi-chopin.dtb$/&\ndtb-$(CONFIG_ARCH_MEDIATEK) += mt6893-oneplus-denniz.dtb/' arch/arm64/boot/dts/mediatek/Makefile
grep -q oneplus-denniz arch/arm64/boot/dts/mediatek/Makefile
sed -i 's|#include "../boot/dts/mediatek/mt6893-xiaomi-chopin.dts"|#include "../boot/dts/mediatek/mt6893-oneplus-denniz.dts"|' arch/arm64/kernel/chopin-board.dts
grep -q oneplus-denniz arch/arm64/kernel/chopin-board.dts
sed -i 's/=0x77a20000/=0x78810000/; s/fb_band\t0x77a20000,/fb_band\t0x78810000,/' arch/arm64/kernel/head.S
! grep -q "^[^*]*0x77a20000" arch/arm64/kernel/head.S
sed -i 's/^#define FB_CAND1\t\t0x77a20000U/#define FB_CAND1\t\t0x78810000U\t\/* denniz *\//; s/^#define FB_REGION_SIZE\t\t0x27e0000U.*/#define FB_REGION_SIZE\t\t0x1df0000U\t\/* denniz mblock framebuffer region *\//' drivers/misc/mtk-logstore-console.c
grep -q "FB_CAND1.*0x78810000U" drivers/misc/mtk-logstore-console.c; grep -q "FB_REGION_SIZE.*0x1df0000U" drivers/misc/mtk-logstore-console.c
C=arch/arm64/configs/denniz_defconfig; cp arch/arm64/configs/chopin_defconfig $C
off() { for o in "$@"; do sed -i -E "/^(# )?CONFIG_$o[= ]/d" $C; echo "# CONFIG_$o is not set" >> $C; done; }
off DRM_MEDIATEK DRM_MEDIATEK_V2 DRM_PANEL_K10A_36_02_0A TOUCHSCREEN_NT36xxx_HOSTDL_SPI MTK_BOOT_PROGRESS_FB MTK_SCP_CHOPIN MTK_TINYSYS_SCP_SUPPORT MTK_SENSORHUB MTK_COMBO MTK_BTIF
off USB_G_SERIAL   # legacy g_serial grabs the UDC before our configfs gadget (seen on the first boot)
sed -i -E '/^CONFIG_USB_CONFIGFS=/d; /^CONFIG_CONFIGFS_FS=/d' $C; echo CONFIG_USB_CONFIGFS=y >> $C; echo CONFIG_CONFIGFS_FS=y >> $C
sed -i -E '/^CONFIG_CMDLINE=/d' $C
echo 'CONFIG_CMDLINE="console=tty0 earlycon=mtk8250,mmio32,0x11002000 clk_ignore_unused regulator_ignore_unused pd_ignore_unused ignore_loglevel panic=5 printk.devkmsg=on log_buf_len=4194304 pstore.kmsg_bytes=262144 ramoops.mem_address=0x48090000 ramoops.mem_size=0x8f000 ramoops.record_size=0x1000 ramoops.console_size=0x40000 ramoops.ftrace_size=0 ramoops.pmsg_size=0 rdinit=/init"' >> $C
git add -A arch/arm64/boot/dts/mediatek/mt6893-oneplus-denniz.dts arch/arm64/boot/dts/mediatek/Makefile \
  arch/arm64/kernel/chopin-board.dts arch/arm64/kernel/head.S drivers/misc/mtk-logstore-console.c $C
git commit -q -m "denniz: OnePlus Nord 2 5G first-boot board tree and config" && git log --oneline -2
git diff HEAD~1 --stat
